// ============================================================
// Placement labels
// ============================================================

export const PLACEMENT_LABELS_ES = {
  didNotQualify: "No se ha clasificado",
  winner: "GANADOR",
  podium: "Podio",
  top5: "Top 5",
  leftSide: "Mitad alta de la clasificación",
  qualified: "Clasificado",
} as const

export function translatePlacementLabel(
  original: string,
  language: GameLanguage,
): string {
  if (language === "en") return original

  switch (original) {
    case "Did not qualify":
      return PLACEMENT_LABELS_ES.didNotQualify

    case "WINNER":
      return PLACEMENT_LABELS_ES.winner

    case "Podium":
      return PLACEMENT_LABELS_ES.podium

    case "Top 5":
      return PLACEMENT_LABELS_ES.top5

    case "Left side of the board":
      return PLACEMENT_LABELS_ES.leftSide

    case "Qualified":
      return PLACEMENT_LABELS_ES.qualified

    default:
      return original
  }
}

// ============================================================
// Placement flavour
// ============================================================

export function getPlacementFlavor(
  entry: {
    qualified: boolean
    position: number
    semiPosition: number
    semiPoints: number
  },
  finalists: number,
  language: GameLanguage,
): string {
  if (language === "en") {
    if (!entry.qualified) {
      return `Knocked out in the semi-final — ${entry.semiPosition}${getOrdinal(
        entry.semiPosition,
      )} with ${entry.semiPoints} pts, just short of the Grand Final.`
    }

    if (entry.position === 1) {
      return "Douze points! Your country wins the Grand Final and hosts next year."
    }

    if (entry.position <= 3) {
      return "A place on the podium — the fans are ecstatic."
    }

    if (entry.position <= 5) {
      return "A confident Top 5 finish. The delegation is thrilled."
    }

    if (entry.position <= 10) {
      return "A respectable finish on the left side of the scoreboard."
    }

    return `${entry.position}th of ${finalists} finalists. You made the final, but the points stayed shy.`
  }

  if (!entry.qualified) {
    return `Eliminado en la semifinal — ${entry.semiPosition}${getOrdinal(
      entry.semiPosition,
    )} con ${entry.semiPoints} puntos, quedándose a las puertas de la Gran Final.`
  }

  if (entry.position === 1) {
    return "¡Doce puntos! Tu país gana la Gran Final y organizará el concurso del próximo año."
  }

  if (entry.position <= 3) {
    return "Un puesto en el podio — los fans están eufóricos."
  }

  if (entry.position <= 5) {
    return "Un sólido Top 5. La delegación está encantada."
  }

  if (entry.position <= 10) {
    return "Un resultado respetable en la mitad alta de la clasificación."
  }

  return `${entry.position}.º de ${finalists} finalistas. Llegaste a la final, pero los puntos no fueron suficientes.`
}

// ============================================================
// Ordinals
// ============================================================

export function getOrdinal(
  n: number,
  language: GameLanguage = "en",
): string {
  if (language === "es") {
    return "º"
  }

  const s = ["th", "st", "nd", "rd"]
  const v = n % 100

  return s[(v - 20) % 10] ?? s[v] ?? s[0]
}

// ============================================================
// Season title
// ============================================================

export function getTranslatedSeasonTitle(
  year: number,
  hostName: string,
  city: string,
  language: GameLanguage,
): string {
  const translatedCity = getCityName(city, language)
  const translatedCountry = hostName

  if (language === "en") {
    return `${translatedCity} (${translatedCountry}) ${year}`
  }

  return `${translatedCity} (${translatedCountry}) ${year}`
}

