// ============================================================
// Complete decision object helper
// ============================================================

export function translateDecision(
  decision: {
    id: string
    role: string
    prompt: string
    left: { label: string }
    right: { label: string }
  },
  language: GameLanguage,
) {
  if (language === "en") {
    return {
      ...decision,
      role: decision.role,
      prompt: decision.prompt,
      left: decision.left.label,
      right: decision.right.label,
    }
  }

  return {
    ...decision,
    role: translateDecisionRole(
      decision.id,
      decision.role,
      language,
    ),
    prompt: translateDecisionPrompt(
      decision.id,
      decision.prompt,
      language,
    ),
    left: translateDecisionChoice(
      decision.id,
      "left",
      decision.left.label,
      language,
    ),
    right: translateDecisionChoice(
      decision.id,
      "right",
      decision.right.label,
      language,
    ),
  }
}

// ============================================================
// Complete contest event helper
// ============================================================

export function translateEvent(
  event: {
    id: string
    text: string
    effect: Record<string, number>
  },
  language: GameLanguage,
) {
  return {
    ...event,
    text: translateContestEvent(
      event.id,
      event.text,
      language,
    ),
  }
}

// ============================================================
// Complete withdrawal helper
// ============================================================

export function translateWithdrawal(
  withdrawal: {
    country: {
      id: string
      name: string
    }
    reason: string
  },
  language: GameLanguage,
) {
  return {
    ...withdrawal,
    country: {
      ...withdrawal.country,
      name: getCountryName(
        withdrawal.country.id,
        withdrawal.country.name,
        language,
      ),
    },
    reason: translateWithdrawalReason(
      withdrawal.reason,
      language,
    ),
  }
}

// ============================================================
// Complete song helper
// ============================================================
//
// Song titles and artist names are intentionally NOT translated.
// They represent fictional Eurovision entries and should remain
// in the language generated by the game.
//
// Only the genre name is localized.
//

export function translateSong(
  song: {
    title: string
    artist: string
    genre: {
      name: string
      song: number
      staging: number
    }
    native: boolean
    veteran: boolean
  },
  language: GameLanguage,
) {
  return {
    ...song,
    genre: {
      ...song.genre,
      name: getGenreName(
        song.genre.name,
        language,
      ),
    },
  }
}

// ============================================================
// Country helper
// ============================================================

export function translateCountry(
  country: {
    id: string
    name: string
    city: string
    alternativeCities: string[]
  },
  language: GameLanguage,
) {
  return {
    ...country,
    name: getCountryName(
      country.id,
      country.name,
      language,
    ),
    city: getCityName(
      country.city,
      language,
    ),
    alternativeCities: country.alternativeCities.map(
      (city) => getCityName(city, language),
    ),
  }
}